{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2159-06-09 10:30:00",
      "speaker": "Doctor",
      "text": "Good morning. I'm Dr. Lee, one of your surgical doctors. You're here because of severe pain and poor circulation in your right leg, correct?"
    },
    {
      "turn_number": 2,
      "time": "2159-06-09 10:31:00",
      "speaker": "Patient",
      "text": "Yes, the pain has been unbearable. I can't sleep, and the skin on my calf is blackening."
    },
    {
      "turn_number": 3,
      "time": "2159-06-09 10:32:00",
      "speaker": "Doctor",
      "text": "I understand. Given the demarcation and eschar, we believe amputation is the best option to relieve your pain and prevent infection from spreading."
    },
    {
      "turn_number": 4,
      "time": "2159-06-09 10:33:00",
      "speaker": "Patient",
      "text": "I was afraid of that. Will it be below the knee?"
    },
    {
      "turn_number": 5,
      "time": "2159-06-09 10:34:00",
      "speaker": "Doctor",
      "text": "We plan for a below-knee amputation. But we’ll assess the skin quality during surgery. If the blood supply is too poor, we might need to go higher."
    },
    {
      "turn_number": 6,
      "time": "2159-06-09 10:35:00",
      "speaker": "Patient",
      "text": "Okay. I trust you. What about my other leg?"
    },
    {
      "turn_number": 7,
      "time": "2159-06-09 10:36:00",
      "speaker": "Doctor",
      "text": "We’ll monitor it closely. You have peripheral vascular disease in both legs, but the left is still well perfused for now."
    },
    {
      "turn_number": 8,
      "time": "2159-06-09 10:37:00",
      "speaker": "Patient",
      "text": "And my heart? I’m on warfarin."
    },
    {
      "turn_number": 9,
      "time": "2159-06-09 10:38:00",
      "speaker": "Doctor",
      "text": "Yes, we’ve stopped your warfarin for safety. We’re using a heparin drip to protect your mechanical valve during surgery."
    },
    {
      "turn_number": 10,
      "time": "2159-06-09 10:39:00",
      "speaker": "Patient",
      "text": "That makes sense. When will the surgery be?"
    },
    {
      "turn_number": 11,
      "time": "2159-06-09 10:40:00",
      "speaker": "Doctor",
      "text": "Today. The team is preparing the operating room now. We’ll give you a regional block to help with pain afterward."
    },
    {
      "turn_number": 12,
      "time": "2159-06-09 10:41:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 13,
      "time": "2159-06-09 12:30:00",
      "speaker": "Doctor",
      "text": "The surgery is complete. We performed a right below-the-knee amputation. The incision looks good, and we were able to preserve enough skin for closure."
    },
    {
      "turn_number": 14,
      "time": "2159-06-09 12:31:00",
      "speaker": "Patient",
      "text": "I’m so glad it’s over. The pain was terrible."
    },
    {
      "turn_number": 15,
      "time": "2159-06-09 12:32:00",
      "speaker": "Doctor",
      "text": "We have you on a PCA pump with dilaudid for pain. The acute pain team also started a ketamine drip because phantom limb pain can be intense."
    },
    {
      "turn_number": 16,
      "time": "2159-06-09 12:33:00",
      "speaker": "Patient",
      "text": "Phantom pain? Like I’ll feel my foot still there?"
    },
    {
      "turn_number": 17,
      "time": "2159-06-09 12:34:00",
      "speaker": "Doctor",
      "text": "Exactly. It’s common after amputation. It doesn’t mean anything’s wrong—it’s just your nerves adjusting."
    },
    {
      "turn_number": 18,
      "time": "2159-06-10 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs are stable. We placed a PICC line yesterday for antibiotics and fluids. The chest X-ray confirms it’s in the right spot."
    },
    {
      "turn_number": 19,
      "time": "2159-06-10 08:01:00",
      "speaker": "Patient",
      "text": "I felt them putting it in. Is the fluid in my lungs from that?"
    },
    {
      "turn_number": 20,
      "time": "2159-06-10 08:02:00",
      "speaker": "Doctor",
      "text": "No, the X-ray showed a large right pleural effusion. That’s likely from your heart failure. We’ll monitor it and adjust your fluids."
    },
    {
      "turn_number": 21,
      "time": "2159-06-10 08:03:00",
      "speaker": "Patient",
      "text": "Okay. And my dialysis?"
    },
    {
      "turn_number": 22,
      "time": "2159-06-10 08:04:00",
      "speaker": "Doctor",
      "text": "You had hemodialysis yesterday and will continue every other day. The renal team is helping with your electrolytes."
    },
    {
      "turn_number": 23,
      "time": "2159-06-11 09:00:00",
      "speaker": "Doctor",
      "text": "Your stump has some redness and a small area of necrosis. We’re starting vancomycin, ciprofloxacin, and flagyl to treat possible cellulitis."
    },
    {
      "turn_number": 24,
      "time": "2159-06-11 09:01:00",
      "speaker": "Patient",
      "text": "Is it infected?"
    },
    {
      "turn_number": 25,
      "time": "2159-06-11 09:02:00",
      "speaker": "Doctor",
      "text": "There are signs of infection, but we caught it early. Daily dressing changes and antibiotics should control it."
    },
    {
      "turn_number": 26,
      "time": "2159-06-11 09:03:00",
      "speaker": "Patient",
      "text": "I’m worried about healing with my kidney disease."
    },
    {
      "turn_number": 27,
      "time": "2159-06-11 09:04:00",
      "speaker": "Doctor",
      "text": "That’s a valid concern. We’re optimizing your nutrition and calcium levels. The wound team is involved too."
    },
    {
      "turn_number": 28,
      "time": "2159-06-12 10:00:00",
      "speaker": "Doctor",
      "text": "Your pain is improving. We’re transitioning you from the PCA to oral hydromorphone."
    },
    {
      "turn_number": 29,
      "time": "2159-06-12 10:01:00",
      "speaker": "Patient",
      "text": "I still feel like my foot is cramping."
    },
    {
      "turn_number": 30,
      "time": "2159-06-12 10:02:00",
      "speaker": "Doctor",
      "text": "That’s phantom pain. The ketamine drip is helping. We’ll keep it going a few more days."
    },
    {
      "turn_number": 31,
      "time": "2159-06-13 08:30:00",
      "speaker": "Doctor",
      "text": "Your INR is still low. We restarted warfarin, but you’ll go home on a heparin drip until it reaches 2.5–3.5."
    },
    {
      "turn_number": 32,
      "time": "2159-06-13 08:31:00",
      "speaker": "Patient",
      "text": "So I’ll have an IV at the rehab center?"
    },
    {
      "turn_number": 33,
      "time": "2159-06-13 08:32:00",
      "speaker": "Doctor",
      "text": "Yes, just until your warfarin is therapeutic. The rehab team will manage it."
    },
    {
      "turn_number": 34,
      "time": "2159-06-14 09:00:00",
      "speaker": "Doctor",
      "text": "We’re concerned about your left leg. You have significant blockages in the superficial femoral artery."
    },
    {
      "turn_number": 35,
      "time": "2159-06-14 09:01:00",
      "speaker": "Patient",
      "text": "Not another surgery?"
    },
    {
      "turn_number": 36,
      "time": "2159-06-14 09:02:00",
      "speaker": "Doctor",
      "text": "It’s a procedure—angioplasty and stenting. It’s less invasive and should improve blood flow to prevent future issues."
    },
    {
      "turn_number": 37,
      "time": "2159-06-15 07:00:00",
      "speaker": "Doctor",
      "text": "Good news—your vancomycin levels are in range. We’ll continue the antibiotics for now."
    },
    {
      "turn_number": 38,
      "time": "2159-06-15 07:01:00",
      "speaker": "Patient",
      "text": "Any side effects to watch for?"
    },
    {
      "turn_number": 39,
      "time": "2159-06-15 07:02:00",
      "speaker": "Doctor",
      "text": "We’re monitoring your kidney function. So far, no signs of toxicity."
    },
    {
      "turn_number": 40,
      "time": "2159-06-16 10:00:00",
      "speaker": "Doctor",
      "text": "You’ll have the left leg procedure tomorrow—two stents in the superficial femoral artery and angioplasty on the right iliac."
    },
    {
      "turn_number": 41,
      "time": "2159-06-16 10:01:00",
      "speaker": "Patient",
      "text": "Will I need more amputations?"
    },
    {
      "turn_number": 42,
      "time": "2159-06-16 10:02:00",
      "speaker": "Doctor",
      "text": "We’re doing this to prevent that. Improved blood flow should help your tissues stay healthy."
    },
    {
      "turn_number": 43,
      "time": "2159-06-17 13:00:00",
      "speaker": "Doctor",
      "text": "The procedure went well. Both stents are open, and blood flow has improved. You’ll stay on heparin a bit longer."
    },
    {
      "turn_number": 44,
      "time": "2159-06-17 13:01:00",
      "speaker": "Patient",
      "text": "I feel some soreness in my groin."
    },
    {
      "turn_number": 45,
      "time": "2159-06-17 13:02:00",
      "speaker": "Doctor",
      "text": "That’s from the catheter site. We’ll keep an eye on it for bleeding or swelling."
    },
    {
      "turn_number": 46,
      "time": "2159-06-18 08:00:00",
      "speaker": "Doctor",
      "text": "Your stump is healing. The redness is improving with antibiotics."
    },
    {
      "turn_number": 47,
      "time": "2159-06-18 08:01:00",
      "speaker": "Patient",
      "text": "Can I start moving more?"
    },
    {
      "turn_number": 48,
      "time": "2159-06-18 08:02:00",
      "speaker": "Doctor",
      "text": "Physical therapy will help you sit up and transfer safely. But no weight on the right side for several weeks."
    },
    {
      "turn_number": 49,
      "time": "2159-06-19 09:00:00",
      "speaker": "Doctor",
      "text": "Your C. diff test came back negative, so we can stop the flagyl. That’s one less antibiotic."
    },
    {
      "turn_number": 50,
      "time": "2159-06-19 09:01:00",
      "speaker": "Patient",
      "text": "I’ve had diarrhea. Is it from the antibiotics?"
    },
    {
      "turn_number": 51,
      "time": "2159-06-19 09:02:00",
      "speaker": "Doctor",
      "text": "Possibly. We’ll add a probiotic and monitor. But it’s good news it’s not C. diff."
    },
    {
      "turn_number": 52,
      "time": "2159-06-20 10:00:00",
      "speaker": "Doctor",
      "text": "Your phantom pain is much better. We’ve stopped the ketamine drip and reduced your pain meds."
    },
    {
      "turn_number": 53,
      "time": "2159-06-20 10:01:00",
      "speaker": "Patient",
      "text": "I haven’t needed any extra pain pills today."
    },
    {
      "turn_number": 54,
      "time": "2159-06-20 10:02:00",
      "speaker": "Doctor",
      "text": "That’s excellent progress. We’ll keep working on weaning your oxycodone slowly to avoid withdrawal."
    },
    {
      "turn_number": 55,
      "time": "2159-06-21 08:30:00",
      "speaker": "Doctor",
      "text": "Your INR is now 1.4. Still low, so you’ll continue the heparin drip until discharge."
    },
    {
      "turn_number": 56,
      "time": "2159-06-21 08:31:00",
      "speaker": "Patient",
      "text": "When will it get up?"
    },
    {
      "turn_number": 57,
      "time": "2159-06-21 08:32:00",
      "speaker": "Doctor",
      "text": "It takes time. We’ll check it daily. You’ll need to follow up closely after rehab."
    },
    {
      "turn_number": 58,
      "time": "2159-06-22 14:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. The plan is to discharge you to rehab in two days."
    },
    {
      "turn_number": 59,
      "time": "2159-06-22 14:01:00",
      "speaker": "Patient",
      "text": "What will they do there?"
    },
    {
      "turn_number": 60,
      "time": "2159-06-22 14:02:00",
      "speaker": "Doctor",
      "text": "Physical therapy, wound care, and monitoring your anticoagulation. They’ll help you prepare for life after amputation."
    },
    {
      "turn_number": 61,
      "time": "2159-06-23 09:00:00",
      "speaker": "Doctor",
      "text": "Your wound is clean, and you’re off all PRN narcotics. That’s a big milestone."
    },
    {
      "turn_number": 62,
      "time": "2159-06-23 09:01:00",
      "speaker": "Patient",
      "text": "I’m proud of that. I was so dependent on painkillers."
    },
    {
      "turn_number": 63,
      "time": "2159-06-23 09:02:00",
      "speaker": "Doctor",
      "text": "We’ll send instructions to slowly taper your oxycodone over the next week to avoid withdrawal."
    },
    {
      "turn_number": 64,
      "time": "2159-06-24 10:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day. You’re being discharged to extended care. Any last questions?"
    },
    {
      "turn_number": 65,
      "time": "2159-06-24 10:01:00",
      "speaker": "Patient",
      "text": "Yes—what signs should I watch for at home?"
    },
    {
      "turn_number": 66,
      "time": "2159-06-24 10:02:00",
      "speaker": "Doctor",
      "text": "Call if you have fever, increased redness or drainage from the wound, or new pain or discoloration in your left foot."
    },
    {
      "turn_number": 67,
      "time": "2159-06-24 10:03:00",
      "speaker": "Patient",
      "text": "And the heparin?"
    },
    {
      "turn_number": 68,
      "time": "2159-06-24 10:04:00",
      "speaker": "Doctor",
      "text": "Continue until your INR is in range. The rehab team will coordinate that."
    },
    {
      "turn_number": 69,
      "time": "2159-06-24 10:05:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel ready."
    },
    {
      "turn_number": 70,
      "time": "2159-06-24 10:06:00",
      "speaker": "Doctor",
      "text": "You’ve worked hard. Keep up the good work in rehab. We’ll see you in follow-up."
    },
    {
      "turn_number": 71,
      "time": "2159-06-24 10:07:00",
      "speaker": "Patient",
      "text": "I will. Thank you for everything."
    },
    {
      "turn_number": 72,
      "time": "2159-06-24 10:08:00",
      "speaker": "Doctor",
      "text": "You're welcome. Take care."
    },
    {
      "turn_number": 73,
      "time": "2159-06-24 10:09:00",
      "speaker": "Patient",
      "text": "One more thing—should I stop smoking?"
    },
    {
      "turn_number": 74,
      "time": "2159-06-24 10:10:00",
      "speaker": "Doctor",
      "text": "Yes, absolutely. Smoking worsens circulation. Your primary doctor can help you quit."
    },
    {
      "turn_number": 75,
      "time": "2159-06-24 10:11:00",
      "speaker": "Patient",
      "text": "I’ll try. For my legs’ sake."
    },
    {
      "turn_number": 76,
      "time": "2159-06-24 10:12:00",
      "speaker": "Doctor",
      "text": "That’s the spirit. Every step helps."
    },
    {
      "turn_number": 77,
      "time": "2159-06-24 10:13:00",
      "speaker": "Patient",
      "text": "And my diet?"
    },
    {
      "turn_number": 78,
      "time": "2159-06-24 10:14:00",
      "speaker": "Doctor",
      "text": "Low fat, low cholesterol. Continue your kidney-friendly diet as advised."
    },
    {
      "turn_number": 79,
      "time": "2159-06-24 10:15:00",
      "speaker": "Patient",
      "text": "Got it. No heavy lifting either, right?"
    },
    {
      "turn_number": 80,
      "time": "2159-06-24 10:16:00",
      "speaker": "Doctor",
      "text": "Not more than 20 pounds for three weeks. And keep the stump elevated when sitting."
    },
    {
      "turn_number": 81,
      "time": "2159-06-24 10:17:00",
      "speaker": "Patient",
      "text": "No driving?"
    },
    {
      "turn_number": 82,
      "time": "2159-06-24 10:18:00",
      "speaker": "Doctor",
      "text": "Not until cleared by surgery. Safety first."
    },
    {
      "turn_number": 83,
      "time": "2159-06-24 10:19:00",
      "speaker": "Patient",
      "text": "Understood. I’m ready to go."
    },
    {
      "turn_number": 84,
      "time": "2159-06-24 10:20:00",
      "speaker": "Doctor",
      "text": "The transport team is here. Take care, and keep in touch."
    },
    {
      "turn_number": 85,
      "time": "2159-06-24 10:21:00",
      "speaker": "Patient",
      "text": "Thank you again. I’ll do my best."
    }
  ],
  "summary": {
    "admission_start": "2159-06-09 10:30:00",
    "admission_end": "2159-06-24 16:59:00",
    "summary_paragraph": "A woman with end-stage renal disease and severe peripheral vascular disease was admitted for a right below-the-knee amputation due to unrelenting pain and tissue necrosis from ischemia. Postoperatively, she developed cellulitis at the stump site, managed with intravenous antibiotics including vancomycin, ciprofloxacin, and metronidazole. Phantom limb pain was initially severe but improved with a ketamine drip and transition to oral analgesics. A second procedure was performed to place stents in the left superficial femoral artery and perform angioplasty on the right common iliac artery to improve circulation. Her anticoagulation was managed with a heparin drip while warfarin was restarted, though her INR remained subtherapeutic at discharge. She participated in physical therapy, was weaned off narcotics, and was discharged to extended care with plans for wound care, anticoagulation monitoring, and gradual tapering of oxycodone.",
    "problems": [
      "Atherosclerosis of native arteries of the extremities with gangrene",
      "End stage renal disease",
      "Cellulitis and abscess of leg, except foot",
      "Infection (chronic) of amputation stump",
      "Phantom limb (syndrome)",
      "Other acute postoperative pain",
      "Chronic diastolic heart failure",
      "Congestive heart failure, unspecified",
      "Long-term (current) use of anticoagulants",
      "Heart valve replaced by other means",
      "Coronary atherosclerosis of unspecified type of vessel, native or graft",
      "Aortocoronary bypass status",
      "Percutaneous transluminal coronary angioplasty status"
    ]
  }
}
